import{_ as o,o as a,c as t,a0 as r}from"./chunks/framework.CBux2OW7.js";const m=JSON.parse('{"title":"Admin & Dashboard Controllers","description":"","frontmatter":{},"headers":[],"relativePath":"backend/controllers/admin-dashboard.md","filePath":"backend/controllers/admin-dashboard.md"}'),l={name:"backend/controllers/admin-dashboard.md"};function i(d,e,s,n,c,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="admin-dashboard-controllers" tabindex="-1">Admin &amp; Dashboard Controllers <a class="header-anchor" href="#admin-dashboard-controllers" aria-label="Permalink to &quot;Admin &amp; Dashboard Controllers&quot;">​</a></h1><p>These controllers govern the protected routes (<code>/dashboard/*</code>). They require the user to be authenticated via Sanctum/Session and typically demand Admin privileges.</p><h2 id="dashboardcontroller" tabindex="-1"><code>DashboardController</code> <a class="header-anchor" href="#dashboardcontroller" aria-label="Permalink to &quot;`DashboardController`&quot;">​</a></h2><p>The entry point for the backend CMS.</p><ul><li>Aggregates high-level metrics (total articles, active subscribers, recent agent activity).</li><li>Passes this data to <code>Dashboard.jsx</code> to render the Recharts graphs and summary widgets.</li></ul><h2 id="studiocontroller" tabindex="-1"><code>StudioController</code> <a class="header-anchor" href="#studiocontroller" aria-label="Permalink to &quot;`StudioController`&quot;">​</a></h2><p>Handles the manual creation, editing, and deletion of articles.</p><ul><li>Receives the raw HTML payload from the <code>RichEditor</code> (TipTap) component.</li><li><strong>Security:</strong> Validates the input rigorously. Even though it accepts HTML, it must ensure no malicious scripts are injected by a compromised editor account.</li><li>Manages the JSON translation column directly if editors manually correct AI translations.</li></ul><h2 id="scoutqueuecontroller" tabindex="-1"><code>ScoutQueueController</code> <a class="header-anchor" href="#scoutqueuecontroller" aria-label="Permalink to &quot;`ScoutQueueController`&quot;">​</a></h2><p>Manages the <code>ScoutedArticle</code> table (the pre-ingestion RSS data).</p><ul><li>Allows admins to manually view, approve, or delete raw scraped data before the <code>NewsAgent</code> processes it.</li><li>Triggers manual ingestion by calling the <code>NewsService</code> from the UI.</li></ul><h2 id="observabilitycontroller" tabindex="-1"><code>ObservabilityController</code> <a class="header-anchor" href="#observabilitycontroller" aria-label="Permalink to &quot;`ObservabilityController`&quot;">​</a></h2><p>The telemetry hub.</p><ul><li>Reads <code>storage/logs/laravel.log</code> or queries specific logging tables to serve real-time AI API metrics.</li><li>Exposes endpoints that the frontend polls to update the <code>GeminiUsage</code> and <code>FactCheckDashboard</code> components.</li></ul>',14)])])}const b=o(l,[["render",i]]);export{m as __pageData,b as default};
